class ServerItem {final int id;final String name;final String? description;ServerItem.fromJson(Map<String,dynamic> j):id=j['id'],name=j['name'],description=j['description'];}
class HomeScreen extends StatefulWidget{const HomeScreen({super.key});@override State<HomeScreen> createState()=>_HomeScreenState();}
class _HomeScreenState extends State<HomeScreen>{List<ServerItem> servers=[];int? selected;bool loading=true,busy=false;String? error;StreamSubscription? sub,statsSub;Timer? clock;DateTime? connectedAt;Duration elapsed=Duration.zero;SingBoxConnectionStatus status=SingBox.instance.status;SingBoxConnectionStats? stats;String? token;final secure=const FlutterSecureStorage();
@override void initState(){super.initState();sub=SingBox.instance.watchConnectionStatus().listen((s){if(s==SingBoxConnectionStatus.connected&&status!=s){connectedAt=DateTime.now();elapsed=Duration.zero;clock?.cancel();clock=Timer.periodic(const Duration(seconds:1),(_){if(connectedAt!=null&&mounted)setState(()=>elapsed=DateTime.now().difference(connectedAt!));});}else if(s!=SingBoxConnectionStatus.connected){clock?.cancel();connectedAt=null;elapsed=Duration.zero;}if(mounted)setState(()=>status=s);});statsSub=SingBox.instance.watchConnectionStats().listen((s){if(mounted)setState(()=>stats=s);});_auth();_load();}
