Future<void> _auth()async{token=await secure.read(key:'clientToken');if(token!=null)return;final u=TextEditingController(),pw=TextEditingController();bool register=false;final ok=await showDialog<bool>(context:context,barrierDismissible:false,builder:(ctx)=>StatefulBuilder(builder:(ctx,sd)=>AlertDialog(title:Text(register?'ثبت‌نام کاربر':'ورود کاربر'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:u,decoration:const InputDecoration(labelText:'نام کاربری')),TextField(controller:pw,obscureText:true,decoration:const InputDecoration(labelText:'رمز (حداقل ۱۰ حرف)')),TextButton(onPressed:()=>sd(()=>register=!register),child:Text(register?'قبلاً حساب دارم':'حساب ندارم؛ ثبت‌نام'))]),actions:[FilledButton(onPressed:()=>Navigator.pop(ctx,true),child:const Text('ادامه'))])));if(ok!=true)return;try{final r=await http.post(Uri.parse('${AppConfig.apiBaseUrl}/api/client/${register?'register':'login'}'),headers:{'Content-Type':'application/json'},body:jsonEncode({'username':u.text.trim(),'password':pw.text}));if(r.statusCode>=300)throw Exception(jsonDecode(r.body)['detail']??'ورود ناموفق');token=jsonDecode(r.body)['access_token'];await secure.write(key:'clientToken',value:token!);if(mounted)setState((){});}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}}\nFuture<void> _load()async{try{final p=await SharedPreferences.getInstance();final r=await http.get(Uri.parse('${AppConfig.apiBaseUrl}/api/servers')).timeout(const Duration(seconds:12));if(r.statusCode!=200)throw Exception();final list=(jsonDecode(r.body) as List).map((e)=>ServerItem.fromJson(e)).toList();selected=p.getInt('selectedServer');if(selected!=null&&!list.any((s)=>s.id==selected))selected=null;if(mounted)setState(()=>servers=list);}catch(_){error='ارتباط با API برقرار نشد؛ آدرس Backend را بررسی کنید.';}finally{if(mounted)setState(()=>loading=false);}}
Future<void> _connect()async{if(selected==null)return;setState(()=>busy=true);try{final r=await http.get(Uri.parse('${AppConfig.apiBaseUrl}/api/client/servers/$selected/profile'),headers:{'Authorization':'Bearer $token'}).timeout(const Duration(seconds:15));if(r.statusCode==401){final p=await SharedPreferences.getInstance();await secure.delete(key:'clientToken');token=null;await _auth();return;}if(r.statusCode!=200)throw Exception('پروفایل اتصال در دسترس نیست');final link=jsonDecode(r.body)['config'] as String;if(status.isActive)await SingBox.instance.disconnect();await SingBox.instance.connect(link);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('اتصال ناموفق: $e')));}finally{if(mounted)setState(()=>busy=false);}}
Future<void> _disconnect()async{setState(()=>busy=true);try{await SingBox.instance.disconnect();}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('قطع اتصال ناموفق: $e')));}finally{if(mounted)setState(()=>busy=false);}}
String _duration(Duration d)=>'\${d.inHours.toString().padLeft(2,'0')}:\${(d.inMinutes%60).toString().padLeft(2,'0')}:\${(d.inSeconds%60).toString().padLeft(2,'0')}';\nString _bytes(int n)=>n<1024?'$n B':n<1048576?'${(n/1024).toStringAsFixed(1)} KB':'${(n/1048576).toStringAsFixed(1)} MB';
@override Widget build(BuildContext context){final connected=status==SingBoxConnectionStatus.connected;return Scaffold(appBar:AppBar(title:const Text('MahdiVPN'),centerTitle:true,actions:[IconButton(onPressed:_load,icon:const Icon(Icons.refresh))]),body:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:_load,child:ListView(padding:const EdgeInsets.all(20),children:[if(error!=null)Text(error!,style:TextStyle(color:Theme.of(context).colorScheme.error)),Text('سرور خود را انتخاب کنید',style:Theme.of(context).textTheme.titleMedium),const SizedBox(height:10),if(servers.isEmpty)const Card(child:Padding(padding:EdgeInsets.all(16),child:Text('سروری در دسترس نیست'))),...servers.map((s)=>Card(child:RadioListTile<int>(value:s.id,groupValue:selected,title:Text(s.name),subtitle:s.description==null?null:Text(s.description!),onChanged:(v)async{if(connected)await _disconnect();final p=await SharedPreferences.getInstance();await p.setInt('selectedServer',s.id);setState(()=>selected=v);}))),const SizedBox(height:28),Center(child:Container(width:180,height:180,decoration:BoxDecoration(shape:BoxShape.circle,color:connected?Colors.green.withValues(alpha:.12):Theme.of(context).colorScheme.primary.withValues(alpha:.1),border:Border.all(color:connected?Colors.green:Theme.of(context).colorScheme.primary,width:3)),child:Icon(connected?Icons.shield:Icons.shield_outlined,size:76,color:connected?Colors.green:Theme.of(context).colorScheme.primary))),const SizedBox(height:16),Center(child:Text(connected?'متصل':'قطع اتصال',style:Theme.of(context).textTheme.titleLarge)),const SizedBox(height:16),FilledButton.icon(onPressed:busy||selected==null?null:(connected?_disconnect:_connect),icon:busy?const SizedBox(width:18,height:18,child:CircularProgressIndicator(strokeWidth:2)):Icon(connected?Icons.stop:Icons.power),label:Text(busy?'در حال انجام…':connected?'قطع اتصال':'اتصال'),style:FilledButton.styleFrom(minimumSize:const Size.fromHeight(54))),if(connected)Padding(padding:const EdgeInsets.only(top:10),child:Center(child:Text('مدت اتصال: ${_duration(elapsed)}'))),if(connected&&stats!=null)Padding(padding:const EdgeInsets.only(top:18),child:Center(child:Text('↓ ${_bytes(stats!.downloadTotal)}   ↑ ${_bytes(stats!.uploadTotal)}')))])));}
